      helpDutiesTitle: 'Writing Duty and Task Statements',
      helpDutiesLead: '<strong style="color:#1e293b;">Duty statements</strong> name the broad areas of work. According to Norton’s DACUM Handbook, a good duty statement should:',
      helpDutiesLi1: 'Describe a <strong>large area of work</strong> in performance terms',
      helpDutiesLi2: 'Act as the <strong>heading for a group of related tasks</strong> (usually 6–20 tasks per duty)',
      helpDutiesLi3: 'Use <strong>one verb, an object,</strong> and usually a qualifier',
      helpDutiesLi4: 'Stay <strong>general rather than specific</strong> (a chart usually has 6–12 duties)',
      helpDutiesLi5: '<strong>Stand alone</strong> — make sense without naming the job',
