      helpDutiesSource: 'Duty guidance adapted from Norton, R. E., <em>DACUM Handbook</em>.',
      helpDutiesNote: '<strong>The difference that matters:</strong> a duty is a heading, a task is a single observable unit of work with a clear beginning and end. If a “task” covers a whole area of work, it is really a duty — and if a “duty” describes one concrete action, it is really a task.',
