      /* ── Task Verification help modal ── */
      helpTVTitle: 'Why Task Verification Matters',
      helpTVIntro: 'Verification turns the workshop panel’s judgement into evidence you can defend. Rate each task on three independent 0–3 scales. Nothing is added to or removed from the DACUM chart at this stage — verification <strong>prioritises, it does not filter</strong>.',
      helpTVK1: 'Importance',
      helpTVV1: '0 = Not Important, 1 = Somewhat, 2 = Important, 3 = Critical. Governs whether a task is included and how strictly it is assessed later.',
      helpTVK2: 'Frequency',
      helpTVV2: '0 = Rarely, 1 = Sometimes, 2 = Often, 3 = Daily. Count how often <em>the worker</em> performs the task on the job — not how often a single unit, client or product needs it. A car needs a new battery every few years, but a mechanic fits batteries daily. Ask the panel “how often do <em>you</em> do this?” Frequency guides sequencing and practice opportunities — not how long a task is taught.',
      helpTVK3: 'Learning Difficulty',
      helpTVV3: '0 = Easy, 1 = Moderate, 2 = Challenging, 3 = Very Difficult. The main driver of instructional time and practice volume.',
      helpTVK4: 'Data collection mode',
      helpTVV4: 'Choose this first. <em>Workshop</em> records how many panel members chose each level and reports weighted means. <em>Individual / Survey</em> records one respondent’s rating.',
      helpTVK5: 'Complete a task fully',
      helpTVV5: 'All three dimensions must be set before a task counts as Complete and before it enters the Task Score, the Priority Index and the results chart.',
      helpTVK6: 'Results chart',
      helpTVV6: 'The 📊 button opens a grouped bar chart per duty, tasks in DACUM order. The dashed line is that duty’s own average.',
      helpTVBody: '<strong style="color:#1e293b;">What this feeds into.</strong> Verification is an input, not a decision. Its output flows in order into Clustering → Learning Outcomes → Performance Criteria → Modules. Tasks rating high here will generally need more detailed learning outcomes and more precise assessment criteria — but that judgement belongs to those later stages, not this one.',
      helpTVNote: 'The three dimensions do not drive the same decision, so a high total is not by itself a call for intensive training: a daily, critical but <em>easy</em> task raises the score without needing much instructional time. And the duty average is <strong>relative</strong> — in a duty where every task is critical, half will still fall below it. A task below the line stays on the DACUM chart; only the depth of its treatment changes.',
      /* ── Competency Clusters tab ── */
