      clAiTaUsed: '{n} Task Analysis lines of this competency’s tasks (criteria, tools, conditions, safety) are used as the source.',
      clAiTaNone: 'No Task Analysis yet for these tasks: the result rests on the task statements only. Analysing the tasks first gives a sharper Range.',
