      /* ── Clustering help modals ── */
      helpClusterTitle: 'Create Competence Clusters',
      helpClusterIntro: 'Group related tasks into competence clusters based on:',
      helpClusterV1: 'Common purpose or industry objective',
      helpClusterV2: 'Similar workflow or process',
      helpClusterV3: 'Shared knowledge and skills required',
      helpClusterNote: '<strong>Important:</strong> Tasks from different duties can be grouped together if they are related by purpose, process, or required skills!',
      helpNamingTitle: 'Competence Statement Format',
      helpNamingIntro: 'Clusters are created as “Cluster 1”, “Cluster 2”… Rename each one to a competence statement so the cluster says what the worker can DO, not just which group it is.',
      helpNamingK1: 'Structure',
      helpNamingV1: 'Action Verb + Task/Activity (What) + Context (Where/How/Why if relevant)',
      helpNamingK2: 'Example',
      helpNamingV2: '“Calibrate testing equipment according to manufacturer specifications”',
      helpNamingNote: 'Good competence statements are clear, measurable, and include the context or standards that guide performance. Keep the standard (<em>“according to…”, “within ±0.5 mm”</em>) and leave out the purpose (<em>“to ensure…”</em>) — the standard is what can be assessed.',
      helpPCTitle: 'What are Performance Criteria and Range?',
      helpPCSourcesNote: '<strong>Two sources, one list.</strong> Criteria written per task in Task Analysis appear first in each competency, read-only; the criteria typed in the box follow them. Adding Task Analysis criteria later renumbers the typed ones — learning outcomes follow automatically. Do not write the same criterion in both places: it would be counted twice.',
      helpPCLead: '<strong style="color:#1e293b;">Performance Criteria</strong> define the standards to which a competency must be performed. They should be:',
      helpPCLi1: '<strong>Observable</strong> — can be seen or detected during assessment',
      helpPCLi2: '<strong>Measurable</strong> — can be evaluated against a standard',
      helpPCLi3: '<strong>Learner-focused</strong> — describes what the learner must demonstrate',
      helpPCRangeLead: '<strong style="color:#1e293b;">Range</strong> defines the scope and context in which the competency is applied, including:',
      helpPCRange1: 'Different situations, environments, or conditions',
      helpPCRange2: 'Types of equipment, tools, or materials used',
      helpPCRange3: 'Variable contexts that may affect performance',
      helpPCComponents: 'Components of an effective performance criterion:',
      helpPCWhat: 'What (Object)',
      helpPCWhatDesc: 'The thing being acted upon',
      helpPCAction: 'Action (Verb)',
      helpPCActionDesc: 'The precise action being performed',
      helpPCQualifier: 'Qualifier',
      helpPCQualifierDesc: 'Specific conditions, standards, or requirements',
      helpPCExampleLabel: 'Example Structure:',
      helpPCExPart1: 'Equipment calibration',
      helpPCExPart2: 'is verified',
      helpPCExPart3: 'to be within manufacturer’s tolerance ranges',
      chipWhat: 'What',
      chipAction: 'Action',
      chipQualifier: 'Qualifier',
      /* ── Learning Outcomes tab ── */
      h2LearningOutcomes: 'Learning Outcomes',
      ttLOHelp: 'Learning Outcome design patterns',
      aiLOTitle: 'Generate Learning Outcomes',
      aiLODesc: 'Choose the design pattern — you can use a different one for each cluster',
      btnPatternA: 'Pattern A — One-to-One',
      btnPatternB: 'Pattern B — Many-to-One',
