      /* ── Task Verification help modal ── */
      helpTVTitle: 'Pourquoi la vérification des tâches compte',
      helpTVIntro: 'La vérification transforme le jugement du panel en preuves défendables. Évaluez chaque tâche sur trois échelles indépendantes 0–3. Rien n’est ajouté ni retiré de la fiche DACUM à ce stade — la vérification <strong>hiérarchise, elle ne filtre pas</strong>.',
      helpTVK1: 'Importance',
      helpTVV1: '0 = pas important, 1 = un peu, 2 = important, 3 = critique. Détermine l’inclusion d’une tâche et la rigueur de son évaluation ultérieure.',
      helpTVK2: 'Fréquence',
      helpTVV2: '0 = rarement, 1 = parfois, 2 = souvent, 3 = quotidien. Comptez la fréquence à laquelle <em>le travailleur</em> effectue la tâche — non celle du besoin d’un client ou d’un produit. Une voiture change de batterie tous les quelques ans, mais un mécanicien en pose chaque jour. Demandez au panel : « à quelle fréquence <em>vous</em> le faites ? »',
      helpTVK3: 'Difficulté d’apprentissage',
      helpTVV3: '0 = facile, 1 = modérée, 2 = exigeante, 3 = très difficile. Principal déterminant du temps d’enseignement et du volume de pratique.',
      helpTVK4: 'Mode de collecte des données',
      helpTVV4: 'À choisir en premier. <em>Atelier</em> enregistre combien de membres ont choisi chaque niveau et calcule des moyennes pondérées. <em>Individuel / enquête</em> enregistre l’évaluation d’un seul répondant.',
      helpTVK5: 'Compléter entièrement une tâche',
      helpTVV5: 'Les trois dimensions doivent être renseignées avant qu’une tâche soit comptée comme complète et entre dans le score, l’indice de priorité et le graphique.',
      helpTVK6: 'Graphique des résultats',
      helpTVV6: 'Le bouton 📊 ouvre un histogramme groupé par activité, tâches dans l’ordre DACUM. La ligne pointillée est la moyenne de cette activité.',
      helpTVBody: '<strong style="color:#1e293b;">Ce que cela alimente.</strong> La vérification est une entrée, pas une décision. Son résultat alimente dans l’ordre : grappes → résultats d’apprentissage → critères de performance → modules. Les tâches bien notées ici demanderont généralement des résultats plus détaillés — mais ce jugement appartient à ces étapes ultérieures.',
      helpTVNote: 'Les trois dimensions ne pilotent pas la même décision : un total élevé n’appelle pas à lui seul une formation intensive — une tâche quotidienne, critique mais <em>facile</em> élève le score sans exiger beaucoup de temps. Et la moyenne de l’activité est <strong>relative</strong> : là où tout est critique, la moitié restera sous la ligne. Une tâche sous la ligne reste sur la fiche DACUM ; seule la profondeur de son traitement change.',
