      /* ── Task Verification help modal ── */
      helpTVTitle: 'لماذا يهمّ التحقق من المهام',
      helpTVIntro: 'يحوّل التحقق حُكم لجنة الورشة إلى أدلة يمكنك الدفاع عنها. قيّم كل مهمة على ثلاثة مقاييس مستقلة من 0 إلى 3. ولا يُضاف شيء إلى مخطط DACUM ولا يُحذف منه في هذه المرحلة — فالتحقق <strong>يرتّب الأولويات ولا يُصفّي</strong>.',
      helpTVK1: 'الأهمية',
      helpTVV1: '0 = غير مهمة، 1 = مهمة إلى حدٍّ ما، 2 = مهمة، 3 = حرجة. تحكم إدراج المهمة ومدى صرامة تقييمها لاحقاً.',
      helpTVK2: 'التكرار',
      helpTVV2: '0 = نادراً، 1 = أحياناً، 2 = غالباً، 3 = يومياً. احسب كم مرة يؤدي <em>العامل</em> المهمة في عمله — لا كم مرة تحتاجها وحدة أو زبون أو منتج واحد. فالسيارة تحتاج بطارية جديدة كل بضع سنوات، لكن الميكانيكي يركّب البطاريات يومياً. اسأل اللجنة: «كم مرة تفعل <em>أنت</em> هذا؟» التكرار يوجّه التسلسل وفرص التدريب العملي — لا مدة تدريس المهمة.',
      helpTVK3: 'صعوبة التعلّم',
      helpTVV3: '0 = سهلة، 1 = متوسطة، 2 = صعبة، 3 = صعبة جداً. المحرّك الرئيس لزمن التدريس وحجم التدريب العملي.',
      helpTVK4: 'أسلوب جمع البيانات',
      helpTVV4: 'اختره أولاً. نمط <em>الورشة</em> يسجّل كم عضواً في اللجنة اختار كل مستوى ويحسب المتوسطات المرجّحة. ونمط <em>فردي / استبانة</em> يسجّل تقييم مستجيب واحد.',
      helpTVK5: 'أكمِل المهمة بالكامل',
      helpTVV5: 'يجب ضبط الأبعاد الثلاثة جميعاً قبل أن تُحتسب المهمة مكتملة وقبل دخولها في درجة المهمة ومؤشر الأولوية ومخطط النتائج.',
      helpTVK6: 'مخطط النتائج',
      helpTVV6: 'زر 📊 يفتح مخطط أعمدة مجمّعاً لكل واجب، والمهام بترتيب DACUM. والخط المتقطّع هو متوسط ذلك الواجب نفسه.',
      helpTVBody: '<strong style="color:#1e293b;">ماذا يغذّي هذا؟</strong> التحقق مُدخَل لا قرار. ومخرجاته تتدفق بالترتيب إلى: تجمعات الكفاءات ← محصلات التعلم ← معايير الأداء ← الوحدات التعلمية. والمهام التي تحصل على تقييم مرتفع هنا ستحتاج عادةً محصلات تعلم أكثر تفصيلاً ومعايير تقييم أدق — لكن ذلك الحُكم يخصّ تلك المراحل اللاحقة لا هذه.',
      helpTVNote: 'الأبعاد الثلاثة لا تقود القرار نفسه، فالمجموع المرتفع ليس بذاته دعوةً لتدريب مكثّف: فالمهمة اليومية الحرجة لكن <em>السهلة</em> ترفع الدرجة دون أن تحتاج زمن تدريس كبيراً. ومتوسط الواجب <strong>نسبي</strong> — ففي واجبٍ كل مهامه حرجة، سيقع نصفها دون المتوسط رغم ذلك. والمهمة الواقعة تحت الخط تبقى على مخطط DACUM؛ ما يتغيّر هو عمق معالجتها فقط.',
